function prepareState({ snapshot, startedAt }) {
  const state = snapshot ?? {};
  if (!state || typeof state !== "object" || Array.isArray(state))
    throw new Error("Glasp tracking state must be an object.");
  const now = Date.parse(startedAt);
  if (!Number.isFinite(now)) throw new Error("Invalid Glasp run start time.");
  const exportedDocs = state.exportedDocs ?? {};
  if (!exportedDocs || typeof exportedDocs !== "object" || Array.isArray(exportedDocs))
    throw new Error("Glasp exportedDocs must be an object.");
  for (const date of Object.values(exportedDocs))
    if (typeof date !== "string" || !Number.isFinite(Date.parse(date)))
      throw new Error("Glasp tracking dates must be valid timestamps.");
  const base = state.lastRunAt ? Date.parse(state.lastRunAt) : now - 24 * 60 * 60 * 1000;
  if (!Number.isFinite(base)) throw new Error("Invalid saved Glasp checkpoint.");
  return {
    updatedAfter: new Date(base - 5 * 60 * 1000).toISOString(),
    startedAt,
    exportedDocs: { ...exportedDocs },
  };
}

const sd = $getWorkflowStaticData("global");
return [
  {
    json: prepareState({
      snapshot: { lastRunAt: sd.lastRunAt ?? null, exportedDocs: sd.exportedDocs ?? {} },
      startedAt: new Date().toISOString(),
    }),
  },
];

function formatPages({ pages, exportedDocs, startedAt, completedAt }) {
  if (!Array.isArray(pages) || !pages.length || pages.length > 100)
    throw new Error("Expected 1–100 Glasp pages.");
  const results = [];
  for (const page of pages) {
    if (!page || typeof page !== "object" || !Array.isArray(page.results))
      throw new Error("Glasp page is missing results.");
    if (page.nextPageCursor != null && typeof page.nextPageCursor !== "string")
      throw new Error("Invalid Glasp cursor.");
    results.push(...page.results);
  }
  if (pages.at(-1).nextPageCursor)
    throw new Error("Glasp pagination is incomplete; tracking has not advanced.");
  const text = (value, name, fallback = "") => {
    if (value == null) return fallback;
    if (typeof value !== "string") throw new Error("Glasp " + name + " must be text.");
    return value;
  };
  const fresh = [];
  for (const doc of results) {
    if (
      !doc ||
      typeof doc !== "object" ||
      Array.isArray(doc) ||
      typeof doc.id !== "string" ||
      !doc.id
    )
      throw new Error("Glasp document ID must be nonempty text.");
    if (!Array.isArray(doc.highlights)) throw new Error("Glasp highlights must be an array.");
    if (!Object.hasOwn(exportedDocs, doc.id) && doc.highlights.length) fresh.push(doc);
  }
  const tracked = Object.fromEntries(Object.entries(exportedDocs));
  const documents = fresh.map((doc) => {
    const title = text(doc.title, "title") || "Untitled";
    const url = text(doc.url, "url"),
      glasp_url = text(doc.glasp_url, "glasp_url");
    const tags = doc.tags ?? [];
    if (!Array.isArray(tags) || tags.some((tag) => typeof tag !== "string"))
      throw new Error("Glasp tags must be an array of strings.");
    const document_note = text(doc.document_note, "document_note");
    const lines = ["## " + title, "", "**URL:** " + url, "**Glasp:** " + glasp_url];
    if (tags.length) lines.push("**Tags:** " + tags.join(", "));
    if (document_note) lines.push("**Note:** " + document_note);
    lines.push("", "### Highlights", "");
    const highlights = doc.highlights.map((highlight) => {
      if (!highlight || typeof highlight !== "object" || Array.isArray(highlight))
        throw new Error("Glasp highlight must be an object.");
      const timestamp = text(highlight.highlighted_at, "highlighted_at");
      if (!Number.isFinite(Date.parse(timestamp)))
        throw new Error("Glasp highlight time must be valid.");
      const result = {
        id: text(highlight.id, "highlight ID"),
        text: text(highlight.text, "highlight text"),
        note: text(highlight.note, "highlight note"),
        color: text(highlight.color, "highlight color"),
        highlighted_at: timestamp,
      };
      lines.push(
        result.text
          .split("\n")
          .map((line) => "> " + line)
          .join("\n"),
      );
      if (result.note) lines.push("", "**Note:** " + result.note);
      lines.push(
        "",
        "- *" +
          result.color +
          " highlight, " +
          new Date(timestamp).toISOString().slice(0, 10) +
          "*",
        "",
      );
      return result;
    });
    Object.defineProperty(tracked, doc.id, {
      value: completedAt,
      enumerable: true,
      writable: true,
      configurable: true,
    });
    return {
      documentId: doc.id,
      title,
      url,
      glasp_url,
      domain: text(doc.domain, "domain"),
      category: text(doc.category, "category"),
      tags,
      author: text(doc.author, "author"),
      thumbnail_url: text(doc.thumbnail_url, "thumbnail_url"),
      document_note,
      is_favorite: doc.is_favorite ?? false,
      highlightCount: highlights.length,
      highlightsText: highlights
        .map(
          (highlight) => highlight.text + (highlight.note ? " [Note: " + highlight.note + "]" : ""),
        )
        .join("\n\n"),
      highlightsMarkdown: lines.join("\n"),
      highlights,
      createdAt: text(doc.created_at, "created_at"),
      updatedAt: text(doc.updated_at, "updated_at"),
    };
  });
  const oldest = Date.parse(completedAt) - 30 * 24 * 60 * 60 * 1000;
  for (const [id, exportedAt] of Object.entries(tracked))
    if (Date.parse(exportedAt) < oldest) delete tracked[id];
  return {
    documents,
    count: documents.length,
    message: documents.length ? "Highlights prepared." : "No new highlights found.",
    tracking: { lastRunAt: startedAt, exportedDocs: tracked },
  };
}

const prepared = $("Prepare Parameters").first().json;
const pages = $input.all().map((item) => {
  if (item.json.statusCode < 200 || item.json.statusCode >= 300)
    throw new Error("Glasp export failed");
  return item.json.body;
});
const result = formatPages({
  pages,
  exportedDocs: prepared.exportedDocs,
  startedAt: prepared.startedAt,
  completedAt: new Date().toISOString(),
});
const sd = $getWorkflowStaticData("global");
sd.lastRunAt = result.tracking.lastRunAt;
sd.exportedDocs = result.tracking.exportedDocs;
return result.count
  ? result.documents.map((json) => ({ json }))
  : [{ json: { message: result.message, count: 0 } }];
